113	// into any Go value without an error and leaves the zero value behind, which
114	// would silently turn a null signature_verified into false and a null
115	// size_bytes into 0; a required field must reject null like a missing key.
116	func isJSONNull(field json.RawMessage) bool {
117		return string(field) == "null"
118	}
