145	// encoding/json refuses to unmarshal them into an integer.
146	func requiredInt(raw map[string]json.RawMessage, name string) (int64, error) {
147		field, ok := raw[name]
148		if !ok || isJSONNull(field) {
149			return 0, errInvalidInput
150		}
151		var value int64
152		if err := json.Unmarshal(field, &value); err != nil {
153			return 0, errInvalidInput
154		}
155		return value, nil
156	}
