370		sentinels := []error{ErrConflict, ErrNotFound, ErrStorage}
371		for i, one := range sentinels {
372			for j, other := range sentinels {
373				if i == j {
374					continue
375				}
376				if errors.Is(one, other) {
377					t.Fatalf("%v must not match %v", one, other)
378				}
379			}
380		}
381		if !errors.Is(ErrRecordNotFound, ErrRecordNotFound) {
382			t.Fatalf("storage not-found sentinel lost its identity")
383		}
